{
  "symbols": [
    {
      "symbol": "h",
      "name": "ground set size",
      "meaning": "The number of elements in the ground set $[h]$, which is 100.",
      "relation": "count",
      "quote": "Let $[h]=\\{1,\\dots,h\\}$ be the ground set, with $h=100$ (the letter $h$ changes meaning here)."
    },
    {
      "symbol": "T",
      "name": "triple",
      "meaning": "A three-element subset of the ground set $[h]$.",
      "relation": "direct",
      "quote": "A three-element subset $T$ of $[h]$ is a *triple*, and $\\mathcal T$ is the set of all triples."
    },
    {
      "symbol": "\\mathcal T",
      "name": "set of triples",
      "meaning": "The set of all three-element subsets of the ground set.",
      "relation": "direct",
      "quote": "A three-element subset $T$ of $[h]$ is a *triple*, and $\\mathcal T$ is the set of all triples."
    },
    {
      "symbol": "g_T",
      "name": "triple value",
      "meaning": "The value carried by the triple $T$, which the network moves to the triples it reaches.",
      "relation": "direct",
      "quote": "Each triple carries a value $g_T$."
    },
    {
      "symbol": "e",
      "name": "ground element",
      "meaning": "An element of the ground set $[h]$, indexing one central wire.",
      "relation": "direct",
      "quote": "gather puts the sum of the $g_T$ with $e\\in T$ on a central wire $C_e$ for each element $e$ of $[h]$"
    },
    {
      "symbol": "C_e",
      "name": "central wire",
      "meaning": "The central wire for element $e$, which carries the sum of the $g_T$ over triples $T$ containing $e$.",
      "relation": "direct",
      "quote": "gather puts the sum of the $g_T$ with $e\\in T$ on a central wire $C_e$ for each element $e$ of $[h]$"
    },
    {
      "symbol": "A_{ST}",
      "name": "auxiliary wire",
      "meaning": "The auxiliary wire for a neighbor pair $S,T$, which carries a copy of $g_T$ into $S$.",
      "relation": "direct",
      "quote": "For each neighbor pair, an auxiliary wire $A_{ST}$ carries a copy of $g_T$ into $S$, which adds a further $g_T$ to $S$ exactly when $|S\\cap T|=1$."
    },
    {
      "symbol": "J",
      "name": "all-one matrix",
      "meaning": "The $h\\times h$ matrix with every entry equal to 1.",
      "relation": "direct",
      "quote": "Let $J$ be the all-one $h\\times h$ matrix (the letter $J$ changes meaning here), and let the bilinear form on $\\mathbb Q^h$ have matrix $I-J/9$."
    },
    {
      "symbol": "\\mathcal F",
      "name": "label space",
      "meaning": "The space $(\\mathbb Q^h)^{\\otimes 3}$ in which the labels are subspaces.",
      "relation": "direct",
      "quote": "The label space $\\mathcal F=(\\mathbb Q^h)^{\\otimes 3}$ is built from the [Tensor product of vector spaces](tensor-product-of-vector-spaces.md) of three copies of $\\mathbb Q^h$, with the product form, and has dimension $D=h^3$."
    },
    {
      "symbol": "D",
      "name": "label space dimension",
      "meaning": "The dimension of the label space $\\mathcal F$, which is $h^3$.",
      "relation": "count",
      "quote": "The label space $\\mathcal F=(\\mathbb Q^h)^{\\otimes 3}$ is built from the [Tensor product of vector spaces](tensor-product-of-vector-spaces.md) of three copies of $\\mathbb Q^h$, with the product form, and has dimension $D=h^3$."
    },
    {
      "symbol": "\\iota",
      "name": "source index",
      "meaning": "An index $(T_1,T_2,T_3)$ of three triples, which labels one source and one line.",
      "relation": "direct",
      "quote": "For an index $\\iota=(T_1,T_2,T_3)\\in\\mathcal T^3$, the label $U_\\iota$ is the line spanned by $t_{T_1}\\otimes t_{T_2}\\otimes t_{T_3}$, and $N=\\binom h3^3$ counts the indices $\\iota$."
    },
    {
      "symbol": "U_\\iota",
      "name": "index label",
      "meaning": "The label, a line in the label space, spanned by the tensor product of the three indicator vectors of $\\iota$.",
      "relation": "direct",
      "quote": "For an index $\\iota=(T_1,T_2,T_3)\\in\\mathcal T^3$, the label $U_\\iota$ is the line spanned by $t_{T_1}\\otimes t_{T_2}\\otimes t_{T_3}$, and $N=\\binom h3^3$ counts the indices $\\iota$."
    },
    {
      "symbol": "N",
      "name": "index count",
      "meaning": "The number of indices $\\iota$, which is the cube of the number of triples.",
      "relation": "count",
      "quote": "For an index $\\iota=(T_1,T_2,T_3)\\in\\mathcal T^3$, the label $U_\\iota$ is the line spanned by $t_{T_1}\\otimes t_{T_2}\\otimes t_{T_3}$, and $N=\\binom h3^3$ counts the indices $\\iota$."
    },
    {
      "symbol": "P_U",
      "name": "label projection",
      "meaning": "The projection onto the label $U$ along its orthogonal complement $U^\\perp$.",
      "relation": "direct",
      "quote": "Each gate or sink with label $U$ carries the projection $P_U$ onto $U$ along $U^\\perp$, and the source of index $\\iota$ carries $-P_{U_\\iota}$."
    },
    {
      "symbol": "V",
      "name": "larger label",
      "meaning": "A label that contains the label $U$ in the rank count.",
      "relation": "direct",
      "quote": "If $U\\subseteq V$ for labels $U$ and $V$ (here $V$ is a label), then $P_V-P_U$ is the identity on $V\\cap U^\\perp$ and zero on $U\\oplus V^\\perp$, so its rank is $\\dim V-\\dim U$."
    },
    {
      "symbol": "s",
      "name": "total rank",
      "meaning": "The sum of the ranks of the edge differences over all edges, which counts the smaller calls.",
      "relation": "count",
      "quote": "Each edge carries the difference of its endpoint matrices, and $s$ is the sum of the ranks of these differences over all edges."
    },
    {
      "symbol": "L",
      "name": "lost dimension",
      "meaning": "The total dimension lost on decreasing edges, the edges whose label shrinks.",
      "relation": "count",
      "quote": "Let $L$ be the total dimension lost on decreasing edges, the edges whose label shrinks (the letter $L$ changes meaning here)."
    },
    {
      "symbol": "m",
      "name": "paper dimension",
      "meaning": "The dimension of the fixed space in the paper's bound, equal to $D$ here.",
      "relation": "count",
      "quote": "the bound is $s<WD$, the paper's $s<Wm$ with $m=D$ here (the letter $m$ changes meaning here)."
    }
  ],
  "relations": [
    {
      "prerequisite": "linear-network-roles",
      "predicate": "is built inside",
      "quote": "The three-element subset intersection construction is a fixed network of gather, scatter and auxiliary wires, built inside a [Finite linear network with roles and frames](linear-network-roles.md)."
    },
    {
      "prerequisite": "tensor-product-of-vector-spaces",
      "predicate": "is built from",
      "quote": "The label space $\\mathcal F=(\\mathbb Q^h)^{\\otimes 3}$ is built from the [Tensor product of vector spaces](tensor-product-of-vector-spaces.md) of three copies of $\\mathbb Q^h$, with the product form, and has dimension $D=h^3$."
    }
  ]
}

